return_type (*function_pointer_name)(parameter_types); // Declaring a function pointer

// Assigning a function to the pointer
function_pointer_name = &function_name; // or simply function_name

// Invoking the function via pointer
result = (*function_pointer_name)(arguments); // or function_pointer_name(arguments);

code_example:
typedef int (*CompareFunc)(const void *, const void *);

int custom_compare(const void *a, const void *b) {
    // Advanced comparison logic, e.g., complex sorting criteria
    return (*(int*)a - *(int*)b);
}

void sort_with_callback(int *array, size_t size, CompareFunc cmp) {
    // Use qsort with a callback for custom comparison
    qsort(array, size, sizeof(int), cmp);
}

int main() {
    int data[] = {5, 2, 9, 1};
    // Registering a custom comparison callback
    sort_with_callback(data, 4, custom_compare);
    // data is now sorted using the advanced callback
    return 0;
}
